with cte as
(
select 
    market,
    sum(amount_spent) as meta_spend
from bi.mark_dev.int_facebook_categorised
where day like '2026%'
group by all
)
, cte2 as
(
select 
    market,
    sum(amount_spent) as meta_spend
from bi.dbt_production_intermediate.int_facebook_categorised
where day like '2026%'
group by all
)
select 
    cte.market,
    cte.meta_spend as new_spend,
    coalesce(cte2.meta_spend, 0) as old_spend,
    round(new_spend - old_spend, 2) as diff
from cte
left join cte2
on cte.market = cte2.market
order by 1;



